	private static final class Capture implements AutoCloseable {
		final Fixture fixture;
		final SyntheticValueSource evaluation;
		final NativeGroupIteration owner;
		final RowState row;
		final LmdbNativeAdaptiveCostModel model = new LmdbNativeAdaptiveCostModel(new LmdbNativeMachineCostModel(),
				new LmdbNativeStoreCostModel(), new LmdbNativeAdaptiveCostModel.Configuration(true, true));
		final LmdbNativeStrategyArbiter<List<BindingSet>> arbiter;
		LmdbNativeStrategyProposal<List<BindingSet>> proposal;

		Capture(Fixture fixture) throws Exception {
			this.fixture = fixture;
			NativeGroupStep step = fixture.step;
			evaluation = SyntheticValueSource.forEvaluation(fixture.guarded);
			evaluation.executionContext().initializeQueryBase(EmptyBindingSet.getInstance());
			owner = new NativeGroupIteration(evaluation, step.arg, step.layout, step.groupSlots, step.aggregates,
					step.strictCompare, EmptyBindingSet.getInstance(), null, null, false, fixture.group);
			owner.alternatives = step.alternatives;
			row = new RowState(evaluation, step.layout, EmptyBindingSet.getInstance(), fixture.group,
					owner.cancellation);
			assertThat(owner.initialize(row)).as("the real compiler frame is seeded before candidate offering")
					.isTrue();
			NativeAggregateCostQuotes quotes = new NativeAggregateCostQuotes(owner, row);
			arbiter = LmdbNativeStrategyArbiter.<List<BindingSet>>forModel(fixture.group, -1D, model)
					.diagnostics(owner.cancellation, 1L, "Census physical recipe")
					.estimateWith(candidate -> {
						if (LmdbNativeCensusAggregate.PATH.equals(candidate.tag)) {
							quotes.attach(candidate);
							proposal = candidate;
						}
					})
					.forcing(LmdbNativeCensusAggregate.PATH, "Census physical recipe");
			owner.offerCandidates(row, LmdbNativeAttemptMetrics.root(fixture.group), step.arg, arbiter);
		}

		JsonNode quote() throws Exception {
			String json = fixture.group.getStringMetricActual(NativeAggregateCostQuotes.METRIC);
			if (json == null) {
				return null;
			}
			for (JsonNode candidate : JsonMapper.builder().build().readTree(json)) {
				if (LmdbNativeCensusAggregate.PATH.equals(candidate.path("strategy").asText())) {
					return candidate;
				}
			}
			return null;
		}

		LmdbNativeCostEstimate estimate() {
			if (proposal == null) {
				return null;
			}
			LmdbNativeCostEstimate estimate = proposal.adaptiveEstimate(-1D);
			return estimate == null ? proposal.directTimingEstimate() : estimate;
		}

		@Override
		public void close() {
			try {
				arbiter.close();
			} finally {
				try {
					row.closeDecodedInputs();
					owner.close();
				} finally {
					evaluation.executionContext().close();
				}
			}
		}
	}

	private static List<BindingSet> evaluate(QueryEvaluationStep step) {
		return new ArrayList<>(QueryResults.asList(step.evaluate(EmptyBindingSet.getInstance())));
	}
